"""RC5 A2 overlay on A1; native DASM via frozen generator."""
from pathlib import Path
a1=Path("tools/build_rc5_a1.py").read_text()
marker="exec(compile(source.replace"
assert a1.count(marker)==1
prefix,suffix=a1.split(marker)
extra="# RC5-A2: delay is dead for moving kind 1/3 until Retire overwrites it.\n# Save derived color without another Random call; all seven RC4 kind values unchanged.\nold=\"\"\"    adc #1\n    sta kind,x\n    lda #8\n    sta pos,x\"\"\"\nnew=\"\"\"    adc #1\n    sta kind,x\n    cmp #1\n    bne A2SpawnPosition\n    lda rng\n    lsr\n    and #7\n    cmp #6\n    bcc A2StoreColor\n    sbc #6\nA2StoreColor:\n    sta delay,x\nA2SpawnPosition:\n    lda #8\n    sta pos,x\"\"\"\nassert engine.count(old)==1\nengine=engine.replace(old,new)\n# Third fish bitmap at fixed single-page address F996. No new RAM or page crossing.\nold='    IF cargo != $F928'\nassert display.count(old)==1\ndisplay=display.replace(old,'FishC: .byte $00,$00,$10,$5C,$7D,$FF,$5C,$40,$00,$00\\n    IF FishC != $F996\\n    ERR\\n    ENDIF\\n'+old)\nold=\"\"\"    lda ObjColor,y\n    sta COLUP1\n    lda #$0E\"\"\"\nnew=\"\"\"    lda #$0E\"\"\"\nassert display.count(old)==1\ndisplay=display.replace(old,new)\n# Color selection moved from water/gate computation to an existing spare line.\nold=\"\"\"    sta gateMid\n    sta WSYNC\n    lda #$30\n    sta PF0\n    lda #4\n    sta COLUBK\n    sta WSYNC\"\"\"\nnew=\"\"\"    sta gateMid\n    sta WSYNC\n    lda #$30\n    sta PF0\n    lda #4\n    sta COLUBK\n    ldy kind,x\n    cpy #1\n    beq A2FishColor\n    cpy #3\n    beq A2FishColor\n    lda ObjColor,y\n    jmp A2ColorReady\nA2FishColor:\n    lda delay,x\n    and #7\n    tay\n    lda FishColors,y\nA2ColorReady:\n    sta COLUP1\n    sta WSYNC\"\"\"\nassert display.count(old)==1\ndisplay=display.replace(old,new)\nold='KeeperTable: .byte <keeper_idle,<keeper_operate,<keeper_error'\nassert display.count(old)==1\ndisplay=display.replace(old,'''    IF TV = 1\nFishColors: .byte $2E,$4C,$9E,$5E,$BE,$CE,$2E,$4C\n    ELSE\nFishColors: .byte $1E,$3C,$AE,$CE,$8E,$6E,$1E,$3C\n    ENDIF\nBombRowColor: .byte $00,$08,$08,$00,$00,$00,$00,$00,$00,$00\n'''+old)\n# Split bomb raster loop; write P1 and color first to preserve left edge.\nold=\"\"\"    lda gateMid\n    sta ENABL\n    sta WSYNC\n    sta WSYNC\n    ldy #0\nObjectRows:\"\"\"\nnew=\"\"\"    lda gateMid\n    sta ENABL\n    ldx lane\n    lda kind,x\n    tax\n    sta WSYNC\n    sta WSYNC\n    ldy #0\n    cpx #2\n    beq A2BombRows\n    cpx #6\n    beq A2BombRows\nObjectRows:\"\"\"\nassert display.count(old)==1\ndisplay=display.replace(old,new)\nold=\"\"\"    cpy #10\n    bne ObjectRows\n    lda #0\n    sta GRP0\"\"\"\nnew=\"\"\"    cpy #10\n    bne ObjectRows\n    beq A2RowsDone\nA2BombRows:\n    lda (p1ptr),y\n    sta GRP1\n    lda BombRowColor,y\n    sta COLUP1\n    lda (p0ptr),y\n    sta GRP0\n    sta WSYNC\n    sta WSYNC\n    iny\n    cpy #10\n    bne A2BombRows\nA2RowsDone:\n    lda #0\n    sta GRP0\"\"\"\nassert display.count(old)==1\ndisplay=display.replace(old,new)\n# Four-step ping-pong A/B/C/B, including fish which have passed the gate.\nold=\"\"\"    cpy #1\n    beq Anim\n    cpy #2\n    bne ArtStore\nAnim:\n    lda motionPhase\n    and #8\n    beq ArtBase\n    lda AltPtr,y\n    bne ArtStore\nArtBase:\n    lda BasePtr,y\"\"\"\nnew=\"\"\"    cpy #1\n    beq A2FishAnim\n    cpy #3\n    beq A2FishAnim\n    cpy #2\n    beq Anim\n    cpy #6\n    bne ArtStore\n    ldy #2\nAnim:\n    lda motionPhase\n    and #8\n    beq ArtBase\n    lda AltPtr,y\n    bne ArtStore\nA2FishAnim:\n    lda motionPhase\n    and #$18\n    beq ArtBase\n    cmp #$10\n    beq A2FishC\n    lda #$82\n    bne ArtStore\nA2FishC:\n    lda #$96\n    bne ArtStore\nArtBase:\n    lda BasePtr,y\"\"\"\nfor name in (\"hud\",\"pres\"):\n    data=locals()[name]\n    assert data.count(old)==1,name\n    if name==\"hud\":hud=data.replace(old,new)\n    else:pres=data.replace(old,new)\n"
exec(compile(prefix+"patch += "+repr(extra)+"\n"+marker+suffix,"tools/build_rc5_a1.py+RC5-A2","exec"))
